          end: Duration(milliseconds: 149770),
          text: 'Tariq looked embarrassed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 150668),
          end: Duration(milliseconds: 152593),
          text: '"Will I be punished?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 152593),
          end: Duration(milliseconds: 157973),
          text: '"You will help replace the planter because you damaged it.',
