        CaptionLine(
          start: Duration(milliseconds: 149827),
          end: Duration(milliseconds: 151257),
          text: 'Tariq smiled at him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 151257),
          end: Duration(milliseconds: 155177),
          text: '"You saved everyone from another wrong accusation."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 155177),
          end: Duration(milliseconds: 159017),
          text: '"That is what friends are for," Wasim said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 159017),
          end: Duration(milliseconds: 162257),
          text: 'But Imaan noticed something else.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 162257),
          end: Duration(milliseconds: 168945),
          text:
              'Wasim had described the red mark before the teacher showed the class the key closely that morning.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 168945),
          end: Duration(milliseconds: 174225),
          text:
              '"Maybe he saw it when she locked the box," Akhlaaq said when she mentioned it later.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 174225),
          end: Duration(milliseconds: 176665),
          text: '"Probably," Imaan agreed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 176665),
          end: Duration(milliseconds: 179425),
          text: '"Then why write it down?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 179425),
          end: Duration(milliseconds: 183185),
          text: '"Because \'probably\' is not the same as \'certainly.\'"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 183997),
          end: Duration(milliseconds: 184945),
          text: 'Akhlaaq grinned.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 184945),
          end: Duration(milliseconds: 187793),
          text: '"You are becoming annoyingly good at this."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 187793),
          end: Duration(milliseconds: 192175),
          text:
              'That afternoon, the security workers returned to finish their job.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 192175),
          end: Duration(milliseconds: 202255),
          text:
              'One of them adjusted the small black device over the office door and another checked a cable running toward Sheikh Uncle\'s room.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 202255),
          end: Duration(milliseconds: 205761),
          text: 'Wasim watched them longer than most children did.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 205761),
          end: Duration(milliseconds: 207941),
          text: 'When he realised Akhlaaq was nearby, he smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 207941),
          end: Duration(milliseconds: 210221),
          text: '"Still hoping for a robot?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 210221),
          end: Duration(milliseconds: 212948),
          text: '"A very small robot," Akhlaaq said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 212948),
          end: Duration(milliseconds: 215781),
          text: '"Possibly one that does homework."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 215781),
          end: Duration(milliseconds: 217221),
          text: 'They laughed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 217221),
          end: Duration(milliseconds: 225741),
          text:
              'Near dismissal, Tariq passed the office and noticed that the blue thread Sheikh Uncle had kept in a clear envelope was no longer on the corner of the desk.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 226306),
          end: Duration(milliseconds: 226883),
          text: '"Sheikh Uncle?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 226883),
          end: Duration(milliseconds: 228729),
          text: 'Where is the thread?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 229129),
          end: Duration(milliseconds: 230729),
          text: 'Sheikh Uncle looked surprised.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 230729),
          end: Duration(milliseconds: 233077),
          text: '"I moved some papers this morning.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 233077),
          end: Duration(milliseconds: 234729),
          text: 'It should still be here."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 234729),
          end: Duration(milliseconds: 236883),
          text: 'They searched the drawer.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 236883),
          end: Duration(milliseconds: 238729),
          text: 'The envelope was gone.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 238729),
          end: Duration(milliseconds: 240799),
          text: 'This time nobody shouted.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 240799),
          end: Duration(milliseconds: 242081),
          text: 'Nobody accused Tariq.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 242574),
          end: Duration(milliseconds: 245697),
          text: 'But everyone understood what it meant.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 245697),
          end: Duration(milliseconds: 249276),
          text: 'Someone was not merely stealing objects.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 249276),
          end: Duration(milliseconds: 251697),
          text: 'Someone was removing clues.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 251697),
          end: Duration(milliseconds: 266468),
          text: 'Challenge of the Day - Protect an Amanah',
        ),
        CaptionLine(
          start: Duration(milliseconds: 266468),
          end: Duration(milliseconds: 282945),
          text:
              'Take one item, duty, message, or responsibility that someone has trusted you with today and protect it carefully. Return it on time, complete the duty properly, and do not use it for yourself without permission.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 284785),
          end: Duration(milliseconds: 293633),
          text:
              'Level-Up: Do the trusted task without reminding people afterward how responsible you were.',
        ),
      ],
    ),
    Story(
      id: 'honesty_en_05',
      title: 'Ep 5 · The Missing Money',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/honesty.webp',
      audioAsset: 'assets/audio/en/honesty/05_the_missing_money.ogg',
