      description: 'The Book of Trust — episode 5 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 0),
          end: Duration(milliseconds: 1709),
          text: 'CHAPTER 5',
        ),
        CaptionLine(
          start: Duration(milliseconds: 1709),
          end: Duration(milliseconds: 4970),
          text: 'The Missing Money',
        ),
        CaptionLine(
          start: Duration(milliseconds: 4970),
          end: Duration(milliseconds: 11938),
          text:
              'Moral Focus: Say only what you know; "I do not know" is honest',
        ),
        CaptionLine(
          start: Duration(milliseconds: 11938),
          end: Duration(milliseconds: 17858),
          text:
              'The disappearance of the blue-thread envelope changed the mood of the mystery.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 17858),
          end: Duration(milliseconds: 23818),
          text:
              'Until then, some students had treated the investigation like an exciting game.',
