        CaptionLine(
          start: Duration(milliseconds: 23818),
          end: Duration(milliseconds: 37346),
          text:
              'Now Sheikh Uncle made the rule clear: nobody was to enter the office without permission, nobody was to search another person\'s belongings, and nobody was to invent theories for entertainment.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 37346),
          end: Duration(milliseconds: 42266),
          text:
              '"A person\'s dignity is more valuable than our curiosity," he said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 42266),
          end: Duration(milliseconds: 45306),
          text: 'The warning was tested before lunchtime.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 46016),
