          text: 'Shahzaib suddenly shouted from his desk.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 49095),
          end: Duration(milliseconds: 51226),
          text: '"My five hundred rupees are gone!"',
        ),
        CaptionLine(
