          text: 'Akhlaaq smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 64190),
          end: Duration(milliseconds: 66470),
          text: '"Welcome to the honest answer.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 66470),
